import os
import json
import re
from configobj import ConfigObj
import urllib3
import time


class APIs:
    """
    Collection of APIs
    """

    EXECUTE_HOOK = "execute-hook"



class Hooks:
    """
    Hooks Collection
    """

    FETCH_DEVICE_IP = "AIG - Get Device IP"
    FETCH_COLLECTION_DETAILS = "Fedex - Fetch Collection Details"


class CommonUtils:
    """
    Execute hooks and Rest API Calls
    """
    def __init__(self, session) -> None:
        """Constructor of the Execute class

        Args:
            session (str): Session ID of the user
        """
        self.session = session
        self.gateway = self.fetch_gateway()


    def fetch_gateway(self):
        """
        fetch the gateway key from appviewx config file
        :return: appviewx gateway key
        """
        abs_path = os.path.dirname(os.path.abspath(__file__))
        prop_file_path = abs_path + "/../../properties/appviewx.properties"
        config = ConfigObj(prop_file_path)
        return config["GATEWAY_BASE_URL"]


    def hit_external_api(
        self, method: str, url: str, header: dict, payload: dict, params: dict = None
    ) -> tuple:
        """
        Method to perform REST APIs through urllib with authentication in header.
        Args:
            Method, URL, Header, payload and params(optional).
        Returns:
            Response.
        """
        try:
            url = url.replace(" ", "%20")
            request = urllib3.PoolManager(cert_reqs="CERT_NONE")
            headers = header
            encoded_data = json.dumps(payload).encode("utf-8")

            if method in ["POST", "PUT"]:
                response = request.request(
                    method, url=url, body=encoded_data, headers=headers
                )

            else:
                response = request.request(
                    method, url=url, fields=params, headers=headers
                )

            if response.status == 200:
                return 200, json.loads(response.data.decode("utf-8"))
            return response.status, json.loads(response.data.decode("utf-8"))

        except Exception as err:
            return "Exception while calling API: " + str(url) + ". Error: " + str(err)


    def execute_urllib(
        self, method: str, url: str, payload: dict, params: dict = None
    ) -> tuple:
        """
        Method to perform REST APIs through urllib.
        Args:
            Method, URL, payload and params(optional).
        Returns:
            Response.
        """
        try:
            url = url.replace(" ", "%20")
            request = urllib3.PoolManager(cert_reqs="CERT_NONE")
            headers = {"Content-Type": "application/json", "sessionId": self.session}
            encoded_data = json.dumps(payload).encode("utf-8")

            if method in ["POST", "PUT"]:
                response = request.request(
                    method, url=url, body=encoded_data, headers=headers
                )

            else:
                response = request.request(
                    method, url=url, fields=params, headers=headers
                )

            if response.status in [200, 201, 202]:
                return 200, json.loads(response.data.decode("utf-8"))

            json_response = json.loads(response.data.decode("utf-8"))
            message = json_response.get("message", "")
            app_status_code = json_response.get("appStatusCode", "N/A")

            if response.status in [500]:
                return f"Internal Server Error while hitting API: {url}. {message}"

            if message and app_status_code:
                return f"Error Occured while hitting API: {url}. Message: {message}. {app_status_code}."

        except Exception as err:
            return "Exception while calling API: " + str(url) + ". Error: " + str(err)


    def execute_query_explorer(self, hook_name, hook_input=None):
        """
        Method to execute the DB query using query explorer via hooks

        Args:
            hook_name: Name of the hook to be executed
            session_id: session ID
            hook_input: Inputs for the 

        Returns:
            response
        """
        gateway_url = self.gateway
        url = f"{gateway_url}avxapi/{APIs.EXECUTE_HOOK}?gwsource=external"
        data = {"payload": {"hook": {"name": hook_name}, "input": hook_input}}
        hook_response = self.execute_urllib("POST", url, data)

        if isinstance(hook_response, tuple):
            response = hook_response[1]
        else:
            return hook_response

        if response:
            if response.get("response") is None:
                return []
            return response.get("response").get("output")

        return []


    def get_collection_details(self):
        message = "Unknown error occured"
        collection_response = self.execute_query_explorer(
            Hooks.FETCH_COLLECTION_DETAILS, {}
        )

        if isinstance(collection_response, str):
            message = "Fetch Collection Details hook failed: " + collection_response + "  because the collection is not imported or not enabled"
            return message

        if collection_response:
            if isinstance(collection_response, list):
                return collection_response
            else:
                message = "Collection details not found"

        else:
            message = "Unable to fetch Collection details"

        return message


def retry(max_retries=3, initial_delay=10):
    def decorator(func):
        def wrapper(*args, **kwargs):
            attempt = 1

            while attempt <= max_retries:
                try:
                    return func(*args, **kwargs)

                except Exception as e:
                    if attempt == max_retries:
                        raise

                    delay = initial_delay * (2 ** (attempt - 1))
                    time.sleep(delay)
                    attempt += 1

        return wrapper

    return decorator


class ServiceNow(CommonUtils):

    def __init__(self, *args, **kwargs) -> None:
        super().__init__(*args, **kwargs)

    @retry()
    def update_ritm(self, snow_url: str, sys_id: str, payload: dict) -> list:
        """Function to update the Service Now Ticket

        Args:
            snow_url (str): Service Now Instance URL
            sys_id (str): Ticket ID
            payload (dict): Payload to be updated

        Returns:
            list: Ticket response
        """
        snow_url = snow_url if snow_url.endswith("/") else f"{snow_url}/"

        try:
            url = f"{snow_url}api/now/table/sc_req_item/{sys_id}"
            inputs = {"url": url, "payload": payload}

            response = self.execute_query_explorer(
                hook_name=Hooks.UPDATE_RITM_TICKET,
                hook_input=inputs,
            )
            response_data = response.get("result", {})

            if response_data:
                return response_data
            else:
                raise Exception("Empty response while updating ticket")

        except Exception as e:
            raise Exception("Error while updating ticket: " + str(e))

    @retry()
    def create_snow_ritm(self, snow_url: str, payload: dict) -> list:
        """Function to create the Service Now Ticket

        Args:
            snow_url (str): Service Now Instance URL
            payload (dict): Payload to be updated

        Returns:
            list: Ticket response
        """
        snow_url = snow_url if snow_url.endswith("/") else f"{snow_url}/"

        try:
            url = f"{snow_url}api/now/table/sc_req_item"
            inputs = {"url": url, "payload": payload}

            response = self.execute_query_explorer(
                hook_name=Hooks.CREATE_SNOW_RITM,
                hook_input=inputs,
            )
            response_data = response.get("result", {})

            if response_data:
                return response_data
            else:
                raise Exception("Empty response while creating RITM ticket")

        except Exception as e:
            raise Exception("Error while creating ticket: " + str(e))

    @retry()
    def get_assignment_group_sys_id(self, snow_url: str, assignment_group: str) -> list:
        """
        Method to create the Service Now Ticket

        Args:
            snow_url (str): Service Now Instance URL
            assignment_group (str): Assignment Group 

        Returns:
            list: Ticket response
        """
        snow_url = snow_url if snow_url.endswith("/") else f"{snow_url}/"

        try:
            # <%snow_url%>/api/now/table/sc_req_item
            url = f"{snow_url}/api/now/table/sys_user_group?sysparm_query=nameLIKE{assignment_group}&sysparm_fields=sys_id%2Cname&sysparm_limit=1"
            inputs = {"url": url}
            response = self.execute_query_explorer(
                hook_name=Hooks.GET_ASSIGNMENT_GROUP_SYS_ID,
                hook_input=inputs,
            )
            response_data = response.get("result", {})
            if response_data:
                return response_data
            else:
                raise Exception("Empty response while getting assignment group Id")
        except Exception as e:
            raise Exception("Error while getting assignment group Id: " + str(e))
